import{u as n,j as e,i}from"./index-BUNYs1Wk.js";import{u as a}from"./useDocumentTitle-CYelJPaR.js";import{A as u}from"./ArchMaskImage-hx2KG737.js";import{B as c}from"./BotanicalBackdrop-j_lQdS18.js";const m=[{name:"Fresh Mushrooms",text:"For everyday cooking and food preparation — a versatile ingredient for homes, restaurants, and food businesses."},{name:"Mushroom Spawn",text:"The essential starting material for mushroom cultivation, intended for growers and enthusiasts."},{name:"Sun-Dried Mushrooms",text:"A convenient way to enjoy mushrooms beyond their fresh form — stored and used across many recipes."},{name:"Mushroom Powder",text:"An easy way to add mushroom flavour to cooking and a variety of dishes."},{name:"Mushroom Pickle",text:"A traditional, flavourful form — one of our value-added mushroom products."},{name:"Mushroom Soup Mix",text:"A simple, convenient way to prepare mushroom soup at home."},{name:"Mushroom Chutney",text:"A familiar, enjoyable accompaniment that combines mushrooms with an everyday food format."},{name:"Home Growing Kit",text:"An accessible way to experience mushroom cultivation yourself and see how mushrooms grow."},{name:"Farm Combo Pack",text:"Selected mushroom products together in one convenient package, for exploring more than one product."}],d=[{title:"Our Story",paras:["The story of MANASI MUSHROOM & SPAWN PVT. LTD. began with Mrs. Manasi Pattanayak, the founder behind our journey. With 15 years of experience in mushroom cultivation and the mushroom industry, she has developed valuable practical knowledge through years of working directly with mushrooms — cultivation, production, handling, and mushroom-based products.","What started as a journey in mushroom cultivation gradually developed into a larger vision. Years of experience, learning, experimentation, and dedication created the foundation for building a professionally structured mushroom business.","In 2026, this journey took an important step forward when the business was officially registered as MANASI MUSHROOM & SPAWN PVT. LTD. — combining years of practical experience with a growing vision for the future."]},{title:"Our Roots",paras:["Our roots are based in Pedagadi, Udala, Mayurbhanj, Odisha. Mushroom cultivation is at the heart of our work, and our experience in this field continues to guide the way we develop our products and serve our customers.","For us, mushrooms are not simply another product. They represent years of patience, learning, hard work, and dedication — qualities that cultivation demands at every stage.","Today, we continue to build on those roots while working toward creating a trusted mushroom brand that can serve customers across India."]},{title:"What We Do",paras:["MANASI MUSHROOM & SPAWN PVT. LTD. focuses on mushroom cultivation, mushroom spawn production, and mushroom-based food products.","Our work covers different stages of the mushroom journey — from cultivation and spawn production to processing and creating convenient mushroom-based products for everyday use.","Whether someone is looking for fresh mushrooms for cooking, spawn for cultivation, processed products for their kitchen, or a home growing kit, our range is designed to provide different ways to enjoy and explore mushrooms."]}],h=[{title:"Our Commitment To Quality",highlight:"Guaranteed Freshness & Quality.",paras:["Quality is one of the most important values behind MANASI MUSHROOM & SPAWN PVT. LTD. We understand that customers want products they can trust, so we focus on careful cultivation, proper handling, thoughtful processing, and consistency throughout our work.","Whether it is fresh mushrooms, spawn, dried mushrooms, powder, pickle, soup mix, chutney, a growing kit, or a combination of our products, we aim to maintain the same dedication and attention to quality."]},{title:"Our Experience",paras:["Our strongest foundation is experience. Fifteen years of hands-on work in mushroom cultivation has given our founder a practical understanding of the industry, built through direct involvement, continuous learning, and years of working with mushrooms.","As the company moves forward, we combine this experience with modern business practices, better systems, improved product development, and a strong focus on customer satisfaction."]},{title:"Our Vision",paras:["Our vision is to develop MANASI MUSHROOM & SPAWN PVT. LTD. into a trusted mushroom company serving customers across India.","We want to continue developing our products, improving our cultivation practices, expanding our reach, and creating more convenient ways for customers to access mushroom products — while contributing to greater awareness of mushroom cultivation and the possibilities it offers."]},{title:"Growing Across India",highlight:"Supplying Across India With Trust.",paras:["We want to build a company that customers from different parts of India can rely on for mushroom products.","As our company grows, our goal is to expand our reach while maintaining the values that have been part of our journey from the beginning — experience, quality, dedication, and trust."]},{title:"Our Future",paras:["The registration of MANASI MUSHROOM & SPAWN PVT. LTD. in 2026 marks a new chapter, but our journey does not stop here. We see the future as an opportunity to grow, learn, improve, and introduce more mushroom products — while remaining connected to the practical experience that started it all.","Our past gives us experience. Our present gives us purpose. Our future gives us the opportunity to grow."]},{title:"Our Promise",paras:["At MANASI MUSHROOM & SPAWN PVT. LTD., we believe a strong company is built not only through products but also through trust. Every mushroom we cultivate, every product we prepare, and every customer we serve is part of our continuing journey.","Our promise is to work with dedication, maintain our focus on quality, continue learning, and keep developing products that bring the versatility of mushrooms closer to customers."]},{title:"From Our Farm To Your Table",paras:["Our journey began with mushroom cultivation. Over the years, it has grown into a wider vision that includes fresh mushrooms, spawn, dried mushrooms, powder, pickle, soup mix, chutney, home growing solutions, and combination products.","MANASI MUSHROOM & SPAWN PVT. LTD. is not simply about selling mushrooms. It is about building a journey around mushrooms — from cultivation to products, from experience to innovation, and from our roots in Odisha to customers across India."]}],r=({section:t})=>e.jsxs("div",{className:"content-section",children:[e.jsx("h2",{className:"content-title",children:t.title}),t.paras.map((o,s)=>e.jsx("p",{children:o},s)),t.highlight&&e.jsx("span",{className:"content-highlight",children:t.highlight})]}),y=()=>{const{config:t}=n();return a("About Us"),e.jsxs("div",{className:"section-padding rel-section paper-grain",children:[e.jsx(c,{variant:"corner"}),e.jsxs("div",{className:"container",style:{maxWidth:"900px"},children:[e.jsxs("div",{className:"page-hero page-hero-card",style:{textAlign:"center",marginBottom:"48px"},children:[e.jsx("span",{className:"eyebrow",children:"About Us"}),e.jsx("h1",{style:{fontFamily:"var(--font-heading)",fontSize:"var(--text-5xl)",lineHeight:1.1,marginBottom:"16px"},children:"15 Years Of Experience. One Passion."}),e.jsx("p",{style:{fontSize:"1.15rem",color:"#555",fontStyle:"italic",fontFamily:"var(--font-heading)"},children:"A journey grown from the farm — from our roots in Odisha to customers across India."})]}),e.jsx(u,{src:i.hero[1],alt:"Mushroom Cultivation",height:"420px",className:"mb-8"}),e.jsx("p",{className:"content-lead",style:{marginBottom:"var(--space-6)"},children:"Welcome to MANASI MUSHROOM & SPAWN PVT. LTD., a mushroom-focused company built on experience, dedication, quality, and a strong connection with mushroom cultivation. Our journey is rooted in practical knowledge, years of hands-on experience, and a vision to make quality mushroom products accessible to customers across India."}),d.map(o=>e.jsx(r,{section:o},o.title)),e.jsxs("div",{className:"content-section",children:[e.jsx("h2",{className:"content-title",children:"Our Products"}),e.jsx("p",{children:"Our product range represents the versatility of mushrooms and the different ways they can be used."}),e.jsx("div",{className:"product-list-grid",children:m.map(o=>e.jsxs("div",{className:"product-list-item",children:[e.jsx("h4",{children:o.name}),e.jsx("p",{children:o.text})]},o.name))})]}),h.map(o=>e.jsx(r,{section:o},o.title)),e.jsxs("div",{className:"farm-statement",children:[e.jsx("h2",{children:"15 Years Of Experience. One Passion. One Growing Journey."}),e.jsx("p",{children:t.name}),e.jsx("p",{children:"Supplying Across India With Trust. · Guaranteed Freshness & Quality."}),e.jsx("p",{children:"Growing with experience. Creating with care. Building for the future."})]})]})]})};export{y as AboutUs};
